import java.util.*;

public class Main {
    static final long M1 = 1000000007L, M2 = 998244353L, B1 = 911382323L, B2 = 972663749L;

    static class Hasher {
        long[] h1, h2, p1, p2;

        Hasher(String s) {
            int n = s.length();
            h1 = new long[n + 1];
            h2 = new long[n + 1];
            p1 = new long[n + 1];
            p2 = new long[n + 1];
            p1[0] = 1;
            p2[0] = 1;
            for (int i = 0; i < n; i++) {
                long v = s.charAt(i) - 'a' + 1;
                h1[i + 1] = (h1[i] * B1 + v) % M1;
                h2[i + 1] = (h2[i] * B2 + v) % M2;
                p1[i + 1] = p1[i] * B1 % M1;
                p2[i + 1] = p2[i] * B2 % M2;
            }
        }

        long key(int l, int r) {
            long a = ((h1[r] - h1[l] * p1[r - l]) % M1 + M1) % M1;
            long b = ((h2[r] - h2[l] * p2[r - l]) % M2 + M2) % M2;
            return a * M2 + b;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        int n = s.length();
        Hasher hasher = new Hasher(s);
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            Set<Long> seen = new HashSet<>();
            boolean found = false;
            for (int i = 0; i + mid <= n && !found; i++) {
                if (!seen.add(hasher.key(i, i + mid))) found = true;
            }
            if (found) lo = mid;
            else hi = mid - 1;
        }
        System.out.println(lo);
    }
}
